// Must match PDM_WORK_ORDER_TOKEN on the dashboard side (empty = no check)
const TOKEN = "demo-token";

if (TOKEN && msg.req.headers["authorization"] !== "Bearer " + TOKEN) {
    msg.statusCode = 401;
    msg.payload = {error: "missing or wrong bearer token"};
    return [msg, null];
}
const order = msg.payload;
if (!order || !order.work_order_id) {
    msg.statusCode = 400;
    msg.payload = {error: "not a work order"};
    return [msg, null];
}
// The Idempotency-Key header is the work order id: a resend gets the same CMMS number
const orders = flow.get("orders") || {};
const isNew = !orders[order.work_order_id];
if (isNew) {
    const n = (flow.get("counter") || 0) + 1;
    flow.set("counter", n);
    orders[order.work_order_id] = {cmms_id: "CMMS-" + n, order: order};
    flow.set("orders", orders);
}
flow.set("last", order.work_order_id);
const cmmsId = orders[order.work_order_id].cmms_id;
node.status({fill: "green", shape: "dot", text: order.work_order_id + " -> " + cmmsId});

// The answer is the first confirmation the dashboard reads
msg.statusCode = 201;
msg.payload = {id: cmmsId, status: "accepted"};
const summary = {payload: {new: isNew, cmms_id: cmmsId, priority: order.priority, asset: order.asset.name,
                           issue: order.alert.detected_issue, action: order.alert.suggested_action}};
return [msg, summary];

// Only for sending over HTTP: must match PDM_WORK_ORDER_CALLBACK_TOKEN of pdm.work_order_callback
const CALLBACK_TOKEN = "demo-callback";

const notes = {in_progress: "Technician on site", completed: "Repaired and tested", rejected: "Not our asset"};
const id = flow.get("last");
const entry = id && (flow.get("orders") || {})[id];
if (!entry) {
    node.warn("No work order received yet: dispatch one from the dashboard first");
    return null;
}
const replyTo = entry.order.reply_to || {};
msg.topic = replyTo.mqtt_topic || ("pdm/v1/work_orders/" + id + "/status");
msg.url = replyTo.http_url || ("http://localhost:8502/work-orders/" + id + "/status");
msg.headers = {"Authorization": "Bearer " + CALLBACK_TOKEN, "Content-Type": "application/json"};
msg.payload = {status: msg.payload, external_id: entry.cmms_id, note: notes[msg.payload],
               at: new Date().toISOString()};
node.status({fill: "blue", shape: "dot", text: id + ": " + msg.payload.status});
return msg;
